//! Regenerate append-only optional coverage from reviewed source contracts.

use std::path::Path;

const DIRECTORY: &str = "crates/rustleaks-core/default";
const MARKER: &str =
    "\n# Maintained additional coverage; generated by xtask generate native-pack-identity.\n";
const REVIEWED: &str = include_str!("native_coverage/reviewed.json");
const PROVIDERS: &str = include_str!("native_coverage/providers.toml");
const CONNECTIONS: &str = include_str!("native_coverage/connections.toml");

pub(super) fn generate(root: &Path, check: bool) -> Result<(), String> {
    let reviewed: serde_json::Value = serde_json::from_str(REVIEWED)
        .map_err(|error| format!("invalid additional coverage source contract: {error}"))?;
    for (name, key, source, count, additional) in [
        ("rustleaks-providers-v1", "providers", PROVIDERS, 104, 196),
        ("rustleaks-connections-v1", "connections", CONNECTIONS, 6, 8),
    ] {
        validate_source(&reviewed, key, source, additional)?;
        let pack = root.join(DIRECTORY).join(format!("{name}.toml"));
        let current = std::fs::read_to_string(&pack)
            .map_err(|error| format!("cannot read {name}: {error}"))?;
        let prior = current
            .split_once(MARKER)
            .map_or(current.as_str(), |(prior, _)| prior);
        if super::sha256_bytes(prior.as_bytes()) != reviewed[format!("{key}_legacy_toml_sha256")] {
            return Err(format!("{name} prior rule bytes changed"));
        }
        let expected = format!("{prior}{MARKER}{source}");
        write_or_check(&pack, &current, &expected, check)?;

        let path = root.join(DIRECTORY).join(format!("{name}.provenance.json"));
        let current = std::fs::read_to_string(&path)
            .map_err(|error| format!("cannot read {name} provenance: {error}"))?;
        let expected = provenance(&reviewed, key, &current, count)?;
        write_or_check(&path, &current, &expected, check)?;
    }
    let license = root.join(DIRECTORY).join("LICENSE.veles");
    if super::sha256_file(&license)? != reviewed["selection"]["additional_source"]["license_sha256"]
    {
        return Err("additional coverage Apache source license differs".into());
    }
    Ok(())
}

fn validate_source(
    reviewed: &serde_json::Value,
    key: &str,
    source: &str,
    count: usize,
) -> Result<(), String> {
    let source: toml::Value = toml::from_str(source)
        .map_err(|error| format!("invalid additional {key} TOML: {error}"))?;
    validate_rules(reviewed, key, &source, count)
}

fn validate_rules(
    reviewed: &serde_json::Value,
    key: &str,
    source: &toml::Value,
    count: usize,
) -> Result<(), String> {
    let rules = source["rules"]
        .as_array()
        .ok_or("additional rules missing")?;
    let expected = reviewed[key]
        .as_array()
        .ok_or("additional origins missing")?;
    if rules.len() != count || expected.len() != count {
        return Err(format!("additional {key} inventory differs"));
    }
    let prefix = &reviewed["preserved_prefixes"][key];
    let prefix_count = usize::try_from(
        prefix["count"]
            .as_u64()
            .ok_or("preserved source count missing")?,
    )
    .map_err(|_| "preserved source count exceeds usize")?;
    let retained = expected
        .get(..prefix_count)
        .ok_or("preserved source rows missing")?;
    let bytes = serde_json::to_vec(retained)
        .map_err(|error| format!("cannot inspect preserved {key} source: {error}"))?;
    if super::sha256_bytes(&bytes) != prefix["sha256"] {
        return Err(format!("preserved {key} source contracts changed"));
    }
    for (native, expected) in rules.iter().zip(expected) {
        validate_rule(key, native, expected)?;
    }
    Ok(())
}

fn validate_rule(
    key: &str,
    native: &toml::Value,
    expected: &serde_json::Value,
) -> Result<(), String> {
    let native = serde_json::to_value(native)
        .map_err(|error| format!("cannot inspect additional {key} rule: {error}"))?;
    if native != expected["native"] || native["id"] != expected["origin"]["id"] {
        return Err(format!(
            "additional {key} source or native contract differs"
        ));
    }
    Ok(())
}

fn provenance(
    reviewed: &serde_json::Value,
    key: &str,
    current: &str,
    count: usize,
) -> Result<String, String> {
    let mut prior: serde_json::Value = serde_json::from_str(current)
        .map_err(|error| format!("invalid additional {key} provenance: {error}"))?;
    prior
        .as_object_mut()
        .ok_or("provenance must be an object")?
        .remove("additional_coverage_selection");
    prior["rules"]
        .as_array_mut()
        .ok_or("provenance rules missing")?
        .truncate(count);
    let bytes = serde_json::to_vec(&prior)
        .map_err(|error| format!("cannot inspect prior provenance: {error}"))?;
    if super::sha256_bytes(&bytes) != reviewed[format!("{key}_legacy_provenance_sha256")] {
        return Err(format!("{key} prior provenance changed"));
    }
    prior["rules"]
        .as_array_mut()
        .ok_or("provenance rules missing")?
        .extend(
            reviewed[key]
                .as_array()
                .ok_or("additional origins missing")?
                .iter()
                .map(|row| row["origin"].clone()),
        );
    prior["additional_coverage_selection"] = reviewed["selection"].clone();
    serde_json::to_string_pretty(&prior)
        .map(|text| text + "\n")
        .map_err(|error| format!("cannot encode additional {key} provenance: {error}"))
}

fn write_or_check(path: &Path, current: &str, expected: &str, check: bool) -> Result<(), String> {
    if check {
        if current != expected {
            return Err(format!(
                "{} is stale; run xtask generate native-pack-identity",
                path.display(),
            ));
        }
        Ok(())
    } else {
        std::fs::write(path, expected)
            .map_err(|error| format!("cannot write {}: {error}", path.display()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn additional_contract_rejects_dropped_filters_paths_and_source_attribution() {
        let reviewed: serde_json::Value = serde_json::from_str(REVIEWED).unwrap();
        for (key, source, count) in [
            ("providers", PROVIDERS, 196),
            ("connections", CONNECTIONS, 8),
        ] {
            assert!(validate_source(&reviewed, key, source, count).is_ok());
            let original: toml::Value = toml::from_str(source).unwrap();
            // Encoding preserves every unchanged rule, so each mutated rule is
            // checked through its own encoding against its reviewed contract.
            let encoded = toml::to_string(&original).unwrap();
            assert_eq!(toml::from_str::<toml::Value>(&encoded).unwrap(), original);
            let expected = reviewed[key].as_array().unwrap();
            for index in 0..count {
                for field in [
                    "regex",
                    "secretGroup",
                    "keywords",
                    "entropy",
                    "path",
                    "allowlists",
                    "required",
                    "skipReport",
                    "predicate",
                ] {
                    let mut changed = original["rules"][index].clone();
                    let rule = changed.as_table_mut().unwrap();
                    if rule.remove(field).is_none() {
                        rule.insert(field.into(), toml::Value::String("unreviewed".into()));
                    }
                    let mut wrapper = toml::Table::new();
                    wrapper.insert("rules".into(), toml::Value::Array(vec![changed]));
                    let decoded: toml::Value =
                        toml::from_str(&toml::to_string(&wrapper).unwrap()).unwrap();
                    let changed = &decoded["rules"][0];
                    assert!(
                        validate_rule(key, changed, &expected[index]).is_err(),
                        "{key} {index} {field}"
                    );
                    if index == 0 || index + 1 == count {
                        let mut document = original.clone();
                        document["rules"][index] = changed.clone();
                        let document = toml::to_string(&document).unwrap();
                        assert!(
                            validate_source(&reviewed, key, &document, count).is_err(),
                            "{key} {index} {field}"
                        );
                    }
                }
            }
        }
        let root = crate::workspace_root().unwrap();
        assert!(generate(&root, true).is_ok());
        let path = root
            .join(DIRECTORY)
            .join("rustleaks-providers-v1.provenance.json");
        let original = std::fs::read_to_string(path).unwrap();
        let mut changed: serde_json::Value = serde_json::from_str(&original).unwrap();
        changed["rules"][0]["source_pattern"] = serde_json::json!("unreviewed");
        assert!(provenance(&reviewed, "providers", &changed.to_string(), 104).is_err());
    }
}
